import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../core/theme.dart';import '../widgets/ui.dart';
class LoginScreen extends StatefulWidget{const LoginScreen({super.key});@override State<LoginScreen> createState()=>_LoginScreenState();}
class _LoginScreenState extends State<LoginScreen>{final email=TextEditingController(),password=TextEditingController();bool busy=false,obscure=true;String? error;
@override void dispose(){email.dispose();password.dispose();super.dispose();}
Future<void> signIn()async{setState((){busy=true;error=null;});try{await Supabase.instance.client.auth.signInWithPassword(email:email.text.trim(),password:password.text);}catch(e){if(mounted)setState(()=>error='تعذر تسجيل الدخول. تحقق من البريد وكلمة المرور.');}finally{if(mounted)setState(()=>busy=false);}}
Future<void> reset()async{if(email.text.trim().isEmpty){setState(()=>error='أدخل بريدك الإلكتروني أولاً');return;}try{await Supabase.instance.client.auth.resetPasswordForEmail(email.text.trim());if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم إرسال رابط إعادة التعيين إن كان الحساب موجوداً')));}catch(e){if(mounted)setState(()=>error='تعذر إرسال رابط الاستعادة');}}
@override Widget build(BuildContext context)=>Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:440),child:Column(children:[const SaiLogo(size:94),const SizedBox(height:18),const Text('كلية ساي التعليمية اليمنية الصينية',textAlign:TextAlign.center,style:TextStyle(fontWeight:FontWeight.w900,fontSize:21)),const Text('也门赛艾教育学院',style:TextStyle(color:SaiColors.gold)),const SizedBox(height:34),Card(child:Padding(padding:const EdgeInsets.all(22),child:Form(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('تسجيل الدخول',style:TextStyle(fontSize:26,fontWeight:FontWeight.w900)),const Text('ادخل إلى بوابتك الأكاديمية بأمان',style:TextStyle(color:SaiColors.muted)),const SizedBox(height:24),TextField(controller:email,keyboardType:TextInputType.emailAddress,textDirection:TextDirection.ltr,decoration:const InputDecoration(labelText:'البريد الإلكتروني',prefixIcon:Icon(Icons.mail_outline))),const SizedBox(height:14),TextField(controller:password,obscureText:obscure,onSubmitted:(_)=>signIn(),decoration:InputDecoration(labelText:'كلمة المرور',prefixIcon:const Icon(Icons.lock_outline),suffixIcon:IconButton(onPressed:()=>setState(()=>obscure=!obscure),icon:Icon(obscure?Icons.visibility_outlined:Icons.visibility_off_outlined)))),Align(alignment:Alignment.centerLeft,child:TextButton(onPressed:reset,child:const Text('نسيت كلمة المرور؟'))),if(error!=null)Text(error!,style:const TextStyle(color:SaiColors.red)),const SizedBox(height:10),FilledButton(onPressed:busy?null:signIn,child:busy?const SizedBox(height:20,width:20,child:CircularProgressIndicator(color:Colors.white,strokeWidth:2)):const Text('دخول إلى النظام'))])))),const SizedBox(height:20),const Text('Yemen SAI Educational College',style:TextStyle(color:SaiColors.muted,fontSize:12))]))))));}
